const ASSETS = '/assets/';
const photos = {day:ASSETS+'hero-day.webp',night:ASSETS+'hero-night.webp',terrace:ASSETS+'terrace.webp',interior:ASSETS+'interior.webp',coast:ASSETS+'coast.webp',spa:ASSETS+'spa.webp'};
Object.assign(photos,{garden:ASSETS+'garden-walk.webp',facade:ASSETS+'facade.webp',beach:ASSETS+'beach.webp',rooftop:ASSETS+'rooftop.webp',gardenSuite:ASSETS+'garden-suite.webp',penthouse:ASSETS+'penthouse.webp',pool:ASSETS+'pool-detail.webp',parking:ASSETS+'parking.webp',materials:ASSETS+'materials.webp',path:ASSETS+'coastal-path.webp'});
const arrow = '<svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="M7 25 25 7M7 7h18v18" stroke="currentColor" stroke-width="1"/></svg>';
const photo = (key,alt,extra='') => `<div class="photo ${extra}"><img src="${photos[key]}" alt="${alt}" loading="lazy"></div>`;
const footer = () => `<section class="closing reveal"><p>Find the home for your own rhythm — a family retreat, a longer coastal stay, or somewhere familiar to return as the seasons change.</p><button class="text-link" data-contact>Book a call</button></section><footer class="footer" data-light><img src="${photos.rooftop}" alt="AURA rooftop terrace overlooking the Mediterranean" loading="lazy"><a class="to-top" href="#main">To top ↑</a><div class="footer-title"><h2>Endless<br>sea views</h2><p class="script">From your rooftop</p><div class="footer-cta"><a class="text-link" href="/apartments">View available apartments</a><a class="round-button" href="/apartments" aria-label="View available apartments">${arrow}</a></div></div><div class="footer-details"><div><p class="serif">Aura Residence.</p><p class="eyebrow" style="margin-top:20px">New Golden Mile · Estepona</p><p>An imagined Mediterranean address.</p></div><div><button class="text-link" data-contact>Arrange a private viewing</button><p style="margin-top:25px">©2026 AURA Residence</p><div class="copyright"><a href="/privacy.html">Privacy policy</a><a href="/privacy.html">Terms of use</a><span>Imaginary brand · Concept residences</span></div></div></div></footer>`;
const residenceTypes = [
 {type:'ground-floor-basement',title:'Ground floor + basement',image:'gardenSuite',beds:'3',area:'178 — 202 m²',copy:'An independent lower level, a private garden and room to make your own.',label:'Explore garden + basement'},
 {type:'ground-floor',title:'Ground floor',image:'interior',beds:'2',area:'97 — 104 m²',copy:'Open your doors to a garden terrace, where the comfort of home meets the easy rhythm of outdoor life.',label:'Explore garden homes'},
 {type:'penthouse-duplex',title:'Penthouse duplex',image:'penthouse',beds:'2–3',area:'124 — 243 m²',copy:'Two beautifully considered levels, wide coastal views and a rooftop terrace that is entirely your own.',label:'Explore penthouses'}
];
const amenities=[
 {title:'Gated community',image:'garden',copy:'Garden paths connect the homes, creating the intimacy of a private neighbourhood and an easy connection to the landscape.'},
 {title:'Swimming pool',image:'pool',copy:'A saltwater swimming pool, a family pool and shaded places to relax. An invitation to slow down beneath the Mediterranean sky.'},
 {title:'Parking area',image:'parking',copy:'Private parking and practical storage, with connections prepared for electric vehicle charging.'},
 {title:'Spa & gym',image:'spa',copy:'A quiet place for movement and renewal, with a spa pool, sauna and wellness spaces shared only with residents and their guests.'},
 {title:'Landscaping',image:'path',copy:'Fragrant gardens, flowering climbers and shaded paths soften the architecture and keep the coastal landscape close to every home.'}
];
const atelierSection=()=>`<section class="atelier" id="atelier" aria-labelledby="atelier-title"><p class="atelier-note">The AURA Atelier · An architectural study</p><div class="atelier-heading"><div><p class="eyebrow">An original perspective on Mediterranean living</p><h2 id="atelier-title">A different<span class="script">perspective</span></h2></div><p>Turn a little. Stay a while.<br>Discover how light, landscape and architecture come together at AURA.</p></div><div class="atelier-stage" tabindex="0" role="region" aria-label="AURA architectural miniature. Drag horizontally or use the arrow keys to rotate. Choose a view below."><img class="atelier-fallback" src="${photos.pool}" alt="AURA courtyard pool and garden"></div><div class="atelier-controls"><div class="atelier-focus"><div class="atelier-views" role="group" aria-label="Explore the architectural miniature"><button data-atelier-view="gardens" aria-pressed="false">The gardens</button><button data-atelier-view="pool" aria-pressed="true">The pool</button><button data-atelier-view="rooftop" aria-pressed="false">The rooftop</button></div><div aria-live="polite" aria-atomic="true"><h3>The heart of AURA</h3><p class="atelier-description">A courtyard for unhurried mornings. Water, warm stone and places to pause in the shade.</p></div></div><div class="atelier-light"><label for="atelier-hour">Follow the light</label><input id="atelier-hour" type="range" min="7" max="21" step="1" value="10" aria-valuetext="10:00, Morning light"><div class="light-scale" aria-hidden="true"><span>Sunrise</span><span>After dark</span></div><output id="atelier-time" for="atelier-hour">10:00 · Morning light</output></div><div class="atelier-orbit"><p>Drag to explore</p><div><button data-atelier-rotate="-1" aria-label="Rotate model left">←</button><button data-atelier-rotate="reset" aria-label="Reset model view">↺</button><button data-atelier-rotate="1" aria-label="Rotate model right">→</button></div></div></div></section>`;
function home(){return `
<section class="hero" data-light id="hero"><img class="hero-picture day" src="${photos.day}" alt="Sunlit AURA residences surrounding a landscaped courtyard and pool" fetchpriority="high"><img class="hero-picture night" src="${photos.night}" alt="AURA courtyard at blue hour, with softly illuminated homes"><div class="hero-content"><h1><span>Aura</span><span>Residence</span></h1><p class="hero-location">Estepona</p><div class="hero-caption"><h2>A home</h2><div class="day-switch"><button data-day="day" aria-pressed="true">By day</button><button data-day="night" aria-pressed="false">By night</button></div><h2>To come back to</h2></div></div><div class="hero-bottom"><p class="script">Life, at your own pace</p><a class="round-button" href="/apartments" aria-label="Discover AURA residences">${arrow}</a></div></section>
<section class="section" id="concept"><div class="intro-head reveal"><h2 class="script">Costa del Sol</h2><p class="eyebrow">A home by the sea —<br>to enjoy season after season</p></div><div class="benefits">
<article class="benefit reveal"><span class="eyebrow">01 / A natural connection</span><h3 class="serif">Real-life location</h3>${photo('path','A quiet Mediterranean walking path beside the sea')}<p class="body-copy">Set among sunlit beaches, celebrated golf courses and peaceful wellness retreats, AURA brings a sense of escape within easy reach of the best of the coast.</p><p class="eyebrow">A quieter kind of connected living</p></article>
<article class="benefit reveal"><span class="eyebrow">02 / Made to last</span><h3 class="serif">Built to stay</h3>${photo('materials','Travertine, bronze and oak details in the AURA architecture')}<p class="body-copy">The relaxed elegance of classic Marbella, expressed through warm stone, contemporary forms and generous spaces designed for everyday life.</p><p class="eyebrow">Thoughtful architecture, lasting comfort</p></article>
<article class="benefit reveal"><span class="eyebrow">03 / Intimate by design</span><h3 class="serif">Boutique concept</h3>${photo('terrace','Private terrace with flowering pergola and sea views')}<p class="body-copy">An intimate collection of 25 Mediterranean homes, shaped around quiet moments, personal space and the pleasure of living well.</p><p class="eyebrow">Considered homes, connected by nature</p></article></div></section>
<blockquote class="quote reveal">Garden paths lead from one home to the next — a neighbourhood of private retreats, connected by nature.<p class="eyebrow">Architecture team<br>Aura Residence</p></blockquote>
<section class="concept"><div class="concept-image reveal"><img src="${photos.garden}" alt="Travertine loggias and planted gardens at AURA Residence" loading="lazy"></div><div class="section concept-caption"><h2 class="script reveal">The concept</h2><div class="reveal"><h3>Just 25 homes, with a shared appreciation for calm surroundings, thoughtful design and Mediterranean life.</h3><p class="body-copy">The easy spirit of coastal Marbella finds a new expression in natural textures, contemporary architecture and garden spaces designed to be enjoyed.</p></div></div></section>
${atelierSection()}
<section class="section location" id="location"><div class="location-title reveal"><p class="eyebrow" style="margin-bottom:40px">Spain</p><h2 class="display">New Golden</h2><span class="script">Mile</span><div class="display" aria-hidden="true">Estepona</div></div><div class="location-content">${photo('coast','An aerial view of the Mediterranean coastline near Estepona','reveal')}<div class="reveal"><p class="eyebrow">A place to settle into your own rhythm</p><h3>Between Marbella<br>and Estepona</h3><p class="body-copy">Beaches, golf, wellness destinations and favourite local places are all close by. Here, a peaceful setting and a connected address meet — somewhere to enjoy every season.</p><a class="text-link" href="/contact">Discover the location</a></div></div></section>
<section class="coast" data-light><img src="${photos.beach}" alt="Blue Mediterranean water meeting the sunlit coast" loading="lazy"><h2>The coast you<br>imagined <span class="script">yours</span></h2><div class="coast-bottom"><p class="serif" style="font-size:36px">New Golden Mile, Estepona</p><p>Costa del Sol · Spain</p></div></section>
<section class="section" id="residences"><div class="residences-heading reveal"><p class="eyebrow">A home by the sea — to enjoy season after season</p><h2>Space to live.<br>Room to make it yours.</h2></div><div class="residence-grid">${residenceTypes.map(r=>`<article class="residence-card reveal">${photo(r.image,r.title+' at AURA Residence')}<h3>${r.title}</h3><div class="residence-stats"><div><span>Bedrooms</span><b>${r.beds}</b></div><div><span>Area up to</span><b>${r.area}</b></div></div><p class="body-copy">${r.copy}</p><a class="text-link" href="/apartments?type=${r.type}">${r.label}</a></article>`).join('')}</div></section>
<section class="amenities" data-light id="amenities"><img class="amenity-image" src="${photos.garden}" alt="Private landscaped courtyard at AURA Residence" loading="lazy"><div class="amenity-content"><p class="eyebrow">The comfort of a private community</p><h2 id="amenity-title">Gated<br>community</h2><p class="body-copy" id="amenity-copy">${amenities[0].copy}</p></div><div class="amenity-tabs" role="tablist" aria-label="Residence amenities">${amenities.map((a,i)=>`<button role="tab" data-amenity="${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}">${a.title}</button>`).join('')}</div></section>
<section class="living-title reveal"><h2 class="display"><span>The space</span><span>to</span></h2><span class="script">Live in</span></section><section class="living-grid">${photo('terrace','Private terrace with linen seating and a flowering canopy','reveal')}<div class="living-copy reveal"><h3>Your home,<br>your own way</h3><p class="body-copy">Optional touches let you tailor the home to your daily life.</p><p class="body-copy">A private jacuzzi.<br>Electric vehicle charging.<br>Rooftop solar panels.</p><button class="text-link" data-contact>Explore the possibilities</button></div><div class="living-copy reveal"><h3>Every finish has a purpose — comfort that feels beautifully simple.</h3><p class="body-copy">Warm floors throughout. Intelligent climate control. Secure keyless entry. Adjustable shutters. Carefully chosen fittings, with comfort built into every detail.</p></div>${photo('interior','Sunlit open living room opening onto the Mediterranean','reveal')}</section>
<section class="architecture" id="architecture"><h2 class="reveal">Architecture</h2>${photo('facade','AURA facade with rounded stone loggias and timber pergolas','reveal')}<div class="architecture-copy"><h3 class="reveal">Precise modern forms.<br>The warmth, light and textures of the Mediterranean.</h3><div class="reveal"><p class="eyebrow">Imagined by</p><p class="body-copy">Atelier Solana<br>Architecture Studio Maré</p></div></div><div class="project-details"><article class="reveal"><p class="eyebrow">Developer</p><h3>Aura Living Studio</h3><p>A considered vision of contemporary coastal living, conceived as one harmonious neighbourhood.</p></article><article class="reveal"><p class="eyebrow">Sales & marketing</p><h3>Solana Collective</h3><p>An individual approach to finding the home that fits your own way of living.</p></article><article class="reveal"><p class="eyebrow">The vision / 2026</p><h3>A new chapter</h3><p>A new expression of Mediterranean living, with light-filled homes, warm materials and gardens designed to grow more beautiful with time.</p></article></div></section>${footer()}`;}
const numbers=['011','012','031','032','033','034','111','112','113','114','121','122','123','124','131','132','133','134','211','212','213','221','222','223','224'];
const apartments=numbers.map((id,i)=>{const t=i<6?residenceTypes[0]:i<18?residenceTypes[1]:residenceTypes[2];return {id,type:t.type,title:t.title,beds:i<6?3:i<18?2:i%2?3:2,area:i<6?178+i*4:i<18?97+(i%8):124+(i%7)*17,terrace:24+(i%6)*7,floor:i<6?0:i<18?1:2,image:(i<6?['gardenSuite','interior','garden']:i<18?['terrace','gardenSuite','interior']:['penthouse','rooftop','terrace'])[i%3],block:'B'+(1+i%3)}});
const apartmentCard=a=>`<a class="apartment-card" href="/apartments/${a.id}">${photo(a.image,a.title+' — residence '+a.id)}<h2>${a.title}</h2><div class="meta"><span>Residence <span class="number">${a.id}</span></span><span>${a.beds} bedrooms<br>${a.area} m² + ${a.terrace} m² terrace</span></div></a>`;
function catalog(){const selected=new URLSearchParams(location.search).get('type')||'';return `<section class="catalog"><h1 class="page-title">Select an<br>apartment</h1><p class="page-subtitle">25 individual homes. One shared sense of belonging.</p><div class="filters"><label>Residence type<select id="type-filter"><option value="">All residences</option>${residenceTypes.map(r=>`<option value="${r.type}" ${r.type===selected?'selected':''}>${r.title}</option>`).join('')}</select></label><label>Bedrooms<select id="bed-filter"><option value="">All bedrooms</option><option value="2">2 bedrooms</option><option value="3">3 bedrooms</option></select></label><label>Arrange by<select id="sort-filter"><option value="number">Residence number</option><option value="area-up">Area: low to high</option><option value="area-down">Area: high to low</option></select></label><button id="reset-filters">Reset filters</button></div><p class="count" id="result-count" role="status"></p><div class="catalog-grid" id="catalog-grid"></div><p class="empty" id="empty-results" hidden>No homes match these preferences. Try another selection.</p></section>${footer()}`;}
function detail(id){const a=apartments.find(x=>x.id===id);if(!a)return `<section class="plain-page"><h1>Home not found</h1><a class="text-link" href="/apartments">View all residences</a></section>`;document.title=`AURA Residence — Apartment ${a.id}`;return `<section class="detail"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span>/</span><a href="/apartments">Apartments</a><span>/</span><span>${a.id}</span></nav><div class="detail-grid"><div><p class="eyebrow">Your private coastal retreat</p><h1>Residence<br>${a.id}</h1><h2>${a.title}</h2><dl class="stats"><div><dt>Bedrooms</dt><dd>${a.beds}</dd></div><div><dt>Interior area</dt><dd>${a.area} m²</dd></div><div><dt>Terrace</dt><dd>${a.terrace} m²</dd></div><div><dt>Floor / block</dt><dd>${a.floor} / ${a.block}</dd></div></dl><p class="body-copy">Generous living spaces and ${a.beds} welcoming bedrooms open onto a private terrace, with a calm connection to the surrounding ${a.floor===2?'coastal views':'gardens'}.</p><button class="text-link" data-contact data-residence="${a.id}">Submit a request</button><p class="eyebrow" style="margin-top:35px">Pool & gym · Private storage · Parking<br>Climate control · Stone floors · Underfloor heating</p></div>${photo(a.image,'AURA residence '+a.id+' architectural concept')}</div><section class="plan"><h2>A considered layout</h2><p class="body-copy" style="margin-bottom:30px">Illustrative arrangement · ${a.beds} bedrooms · ${a.area} m²</p>${floorplan(a)}<p class="form-note" style="margin-top:20px">Conceptual diagram, not a construction drawing. Areas and availability are illustrative.</p></section><a class="text-link" href="/apartments">View all apartments</a></section>${footer()}`;}
function floorplan(a){return `<svg viewBox="0 0 800 460" role="img" aria-label="Concept floor plan with ${a.beds} bedrooms, open living area and terrace"><g fill="#f2f1e9" stroke="#172439" stroke-width="3"><path d="M70 60h570v280H70z"/><path d="M70 340h640v70H70z" fill="#d9dbd0"/><path d="M70 170h300M220 60v280M370 60v280M500 60v110h140" fill="none"/><path d="M370 220h270" stroke-width="1"/><path d="M390 75h92v55h-92zM390 82h90M515 75h92v55h-92zM515 82h90" stroke-width="1"/><path d="M85 75h112v65H85zM85 87h112M238 75h112v65H238zM238 87h112" fill="#e7e5dc" stroke-width="1"/><path d="M410 250h160v45H410zM435 300h110v25H435z" stroke-width="1"/><circle cx="610" cy="275" r="25" stroke-width="1"/><path d="M85 200h105v40H85zM85 250h105v65H85zM235 190h105v120H235z" stroke-width="1"/></g><g fill="#172439" font-family="Arial,sans-serif" font-size="13" text-anchor="middle"><text x="145" y="158">BEDROOM 1</text><text x="296" y="158">BEDROOM 2</text><text x="295" y="255">${a.beds===3?'BEDROOM 3':'STUDY'}</text><text x="500" y="205">KITCHEN / DINING</text><text x="505" y="325">LIVING</text><text x="140" y="285">BATH / ENTRY</text><text x="385" y="383">PRIVATE TERRACE · ${a.terrace} m²</text><text x="720" y="75">N</text><path d="M720 90v45m-5-35 5-10 5 10" fill="none" stroke="#172439"/></g></svg>`;}
const inlineForm=()=>`<form class="contact-form"><label>Name<input name="name" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label class="wide">Phone<input name="phone" type="tel" autocomplete="tel"></label><label class="wide">Message<textarea name="message" rows="4"></textarea></label><p class="wide form-note">This is an imaginary property demonstration. Your information is not transmitted. <a href="/privacy.html">Privacy & terms</a>.</p><button class="text-link" type="submit">Send enquiry</button></form><div class="confirmation" hidden role="status">Thank you<small>Your enquiry is ready. This demonstration does not send messages.</small></div>`;
function contact(){return `<section class="contact-page"><div><p class="eyebrow" style="margin-bottom:35px">A short conversation. A new beginning.</p><h1>Let's find<br>your place</h1><p class="script">By the sea</p><p class="body-copy">Tell us what home means to you — a family retreat, a longer stay or a familiar place to return.</p>${photo('gardenSuite','A private AURA garden terrace for a quiet conversation')}</div><div>${inlineForm()}</div></section>${footer()}`;}
function privacy(){return `<article class="plain-page"><h1>Privacy & terms</h1><p>AURA Residence is an imaginary property brand. The homes, project information and availability on this website are illustrative and do not constitute a property offer.</p><p>Enquiry forms are demonstration-only. They do not transmit or save personal details. Your browser can remember your cookie preference locally.</p><p>The architectural and lifestyle imagery was generated specifically for AURA. Font services may receive standard connection information when your browser loads the typefaces.</p><a class="text-link" href="/">Back to Aura</a></article>`;}
const path=location.pathname.replace(/\/$/,'');
document.querySelector('#main').innerHTML=path==='/apartments'?catalog():path.startsWith('/apartments/')?detail(path.split('/').pop()):path==='/contact'?contact():path==='/privacy.html'?privacy():home();
const header=document.querySelector('#header');
const amenityPanel=document.querySelector('.amenity-content');if(amenityPanel){amenityPanel.id='amenity-panel';amenityPanel.setAttribute('role','tabpanel');amenityPanel.setAttribute('aria-label','Gated community');document.querySelectorAll('[data-amenity]').forEach(tab=>tab.setAttribute('aria-controls','amenity-panel'));}
function updateHeader(){const light=[...document.querySelectorAll('[data-light]')].some(el=>{const rect=el.getBoundingClientRect();return rect.top<110&&rect.bottom>110});header.classList.toggle('dark',!light);}
window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('visible');observer.unobserve(entry.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));
document.addEventListener('click',e=>{
 const trigger=e.target.closest('[data-contact],[data-menu],[data-close],[data-day],[data-amenity],[data-cookie]');if(!trigger)return;
 if(trigger.hasAttribute('data-contact')){document.querySelector('#menu-dialog').close();const dialog=document.querySelector('#contact-dialog');dialog.querySelector('form').hidden=false;dialog.querySelector('.confirmation').hidden=true;if(trigger.dataset.residence)dialog.querySelector('textarea').value='I would like to know more about residence '+trigger.dataset.residence+'.';dialog.showModal();}
 if(trigger.hasAttribute('data-menu'))document.querySelector('#menu-dialog').showModal();
 if(trigger.hasAttribute('data-close'))trigger.closest('dialog').close();
 if(trigger.hasAttribute('data-day')){document.querySelector('.hero').classList.toggle('is-night',trigger.dataset.day==='night');document.querySelectorAll('[data-day]').forEach(b=>b.setAttribute('aria-pressed',b===trigger));}
 if(trigger.hasAttribute('data-amenity'))activateAmenity(Number(trigger.dataset.amenity));
 if(trigger.hasAttribute('data-cookie')){try{localStorage.setItem('aura-cookie-preference',trigger.dataset.cookie)}catch{}document.querySelector('#cookie').hidden=true;}
});
function activateAmenity(index){const a=amenities[index];const img=document.querySelector('.amenity-image');img.src=photos[a.image];img.alt=a.title+' at AURA Residence';document.querySelector('#amenity-title').textContent=a.title;document.querySelector('#amenity-copy').textContent=a.copy;amenityPanel.setAttribute('aria-label',a.title);document.querySelectorAll('[data-amenity]').forEach((b,i)=>{b.setAttribute('aria-selected',i===index);b.tabIndex=i===index?0:-1});window.dispatchEvent(new CustomEvent('aura:amenity',{detail:{index}}));}
document.querySelector('.amenity-tabs')?.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const current=Number(document.activeElement.dataset.amenity);const index=e.key==='Home'?0:e.key==='End'?amenities.length-1:(current+(e.key==='ArrowRight'?1:-1)+amenities.length)%amenities.length;activateAmenity(index);document.querySelector(`[data-amenity="${index}"]`).focus();});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}}));
document.querySelectorAll('.contact-form').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;form.hidden=true;const result=form.parentElement.querySelector('.confirmation');result.hidden=false;result.tabIndex=-1;result.focus();}));
let savedCookie=false;try{savedCookie=!!localStorage.getItem('aura-cookie-preference')}catch{}document.querySelector('#cookie').hidden=savedCookie;
function updateCatalog(){const type=document.querySelector('#type-filter').value,beds=document.querySelector('#bed-filter').value,sort=document.querySelector('#sort-filter').value;const results=apartments.filter(a=>(!type||a.type===type)&&(!beds||a.beds===Number(beds)));if(sort!=='number')results.sort((a,b)=>sort==='area-up'?a.area-b.area:b.area-a.area);document.querySelector('#catalog-grid').innerHTML=results.map(apartmentCard).join('');document.querySelector('#result-count').textContent=results.length+' residences';document.querySelector('#empty-results').hidden=results.length!==0;const query=new URLSearchParams();if(type)query.set('type',type);history.replaceState(null,'','/apartments'+(query.size?'?'+query:''));window.dispatchEvent(new CustomEvent('aura:catalog-update'));}
if(path==='/apartments'){document.querySelectorAll('.filters select').forEach(select=>select.addEventListener('change',updateCatalog));document.querySelector('#reset-filters').addEventListener('click',()=>{document.querySelectorAll('.filters select').forEach(s=>s.selectedIndex=0);updateCatalog();});updateCatalog();}
